package ru.neverland.archaeology.restoration;

import java.util.*;
import java.util.concurrent.*;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;
import org.bukkit.plugin.java.JavaPlugin;
import ru.neverland.archaeology.service.ArtifactService;
import ru.neverland.core.*;
import static ru.neverland.archaeology.restoration.RestorationBook.*;

/** One acknowledged inventory transition at a time. Uncertain transfers never execute again. */
public final class RestorationTransfer {
    private record Plan(Operation operation,ItemStack[] before,ItemStack[] after,PlayerSaveEvidence.Prepared proof){}
    private final JavaPlugin plugin;private final RestorationRepository repository;private final RestorationItems items;private final ArtifactService artifacts;private final PlayerSaveEvidence evidence;private final Runnable changed;
    private final Map<UUID,Plan> active=new HashMap<>();private final Set<UUID> touched=new HashSet<>();private boolean closing;
    public RestorationTransfer(JavaPlugin plugin,RestorationRepository repository,RestorationItems items,ArtifactService artifacts,PlayerSaveEvidence evidence,Runnable changed){this.plugin=plugin;this.repository=repository;this.items=items;this.artifacts=artifacts;this.evidence=evidence;this.changed=changed;}
    public boolean busy(){return !active.isEmpty();}
    private boolean enabled(){return !closing&&plugin.isEnabled()&&!SuiteState.frozen(plugin.getName())&&plugin.getConfig().getBoolean("restoration.enabled",true)&&repository.writable();}
    private void gate(Player player){if(!enabled()||repository.busy()||busy())throw new IllegalStateException("Реставрация сохраняет изменение или временно недоступна. Предметы не перемещены.");if(!player.hasPermission("townyarchaeology.use")||!player.hasPermission("townyarchaeology.restore"))throw new IllegalStateException("У вас нет доступа к реставрации.");if(repository.state().blocked(player.getUniqueId()))throw new IllegalStateException("Предыдущая передача требует сверки. Повторная выдача заблокирована.");}
    public void claim(Player player,UUID id){try(var guard=SuiteState.guard()){
        gate(player);var book=repository.state();var fragment=book.fragments().get(id);if(fragment==null||fragment.phase()!=FragmentPhase.MAILBOX||!fragment.finder().equals(player.getUniqueId()))throw new IllegalStateException("Эта находка недоступна для получения.");var output=items.create(fragment);var before=copy(player.getInventory().getStorageContents());var after=InventoryPlan.insert(before,output);if(after==null)throw new IllegalStateException("Освободите место в инвентаре.");var operation=new Operation(UUID.randomUUID(),Kind.CLAIM,player.getUniqueId(),player.getName(),System.currentTimeMillis(),fragment.recipe(),List.of(id),id,encode(output),Phase.PREPARED,"Получение подтверждённой находки");prepare(player,operation,before,after);
    }}
    public List<List<Fragment>> groups(Player player,String artifact){var groups=new LinkedHashMap<Recipe,List<Fragment>>();var seen=new HashSet<UUID>();for(var stack:player.getInventory().getStorageContents()){var fragment=items.identify(stack,repository.state());if(fragment==null||fragment.phase()!=FragmentPhase.OWNED||!fragment.recipe().artifact().equals(artifact))continue;if(!seen.add(fragment.id()))throw new IllegalStateException("В инвентаре повторяется UUID фрагмента. Такие копии нельзя использовать.");groups.computeIfAbsent(fragment.recipe(),key->new ArrayList<>()).add(fragment);}return groups.values().stream().map(List::copyOf).toList();}
    public List<Fragment> restorable(Player player,String artifact){for(var group:groups(player,artifact)){var parts=new TreeMap<Integer,Fragment>();for(var f:group)parts.putIfAbsent(f.part(),f);if(parts.size()==group.get(0).recipe().parts())return List.copyOf(parts.values());}return List.of();}
    public void restore(Player player,String artifact){restore(player,artifact,null);}
    public void restore(Player player,String artifact,List<UUID> expected){try(var guard=SuiteState.guard()){
        gate(player);var selected=restorable(player,artifact);if(selected.isEmpty())throw new IllegalStateException("Нужен полный набор разных частей с одинаковым сохранённым рецептом.");if(expected!=null&&!selected.stream().map(Fragment::id).toList().equals(expected))throw new IllegalStateException("Набор частей изменился. Проверьте его и подтвердите реставрацию заново.");
        UUID id=UUID.randomUUID(),outputId=UUID.randomUUID();var output=artifacts.createExact(artifact,outputId);var before=copy(player.getInventory().getStorageContents());var consumed=new HashSet<UUID>();var wanted=new HashSet<UUID>();selected.forEach(f->wanted.add(f.id()));var removed=copy(before);for(int i=0;i<removed.length;i++){var fragment=items.identify(removed[i],repository.state());if(fragment!=null&&wanted.contains(fragment.id())){if(!consumed.add(fragment.id()))throw new IllegalStateException("Обнаружена копия фрагмента.");removed[i]=null;}}if(!consumed.equals(wanted))throw new IllegalStateException("Состав инвентаря изменился; откройте реставрацию заново.");var after=InventoryPlan.insert(removed,output);if(after==null)throw new IllegalStateException("Недостаточно места для восстановленного артефакта.");var operation=new Operation(id,Kind.RESTORE,player.getUniqueId(),player.getName(),System.currentTimeMillis(),selected.get(0).recipe(),selected.stream().map(Fragment::id).toList(),outputId,encode(output),Phase.PREPARED,"Реставрация из точных подписанных частей");prepare(player,operation,before,after);
    }}
    private void prepare(Player player,Operation operation,ItemStack[] before,ItemStack[] after){final PlayerSaveEvidence.Prepared proof;try{proof=evidence.prepare(player,operation.id());}catch(java.io.IOException error){throw new IllegalStateException("Проверка сохранения игрока недоступна. Предметы не перемещены.",error);}var plan=new Plan(operation,before,after,proof);var state=repository.state();var next=state.prepare(operation);active.put(operation.id(),plan);repository.commit(state,next).whenComplete((saved,error)->{if(error!=null){failed(operation.id(),error);return;}onPlayer(player,operation.id(),()->arm(player,plan));});}
    private void arm(Player player,Plan plan){if(!current(player,plan)){cancelUntouched(plan,"Инвентарь или доступ изменились до передачи");return;}var state=repository.state();repository.commit(state,state.arm(plan.operation().id())).whenComplete((saved,error)->{if(error!=null){failed(plan.operation().id(),error);return;}onPlayer(player,plan.operation().id(),()->apply(player,plan));});}
    private boolean current(Player player,Plan plan){return enabled()&&player.isOnline()&&player.hasPermission("townyarchaeology.use")&&player.hasPermission("townyarchaeology.restore")&&Arrays.equals(plan.before(),player.getInventory().getStorageContents());}
    private void apply(Player player,Plan plan){if(!current(player,plan)){cancelUntouched(plan,"Инвентарь или доступ изменились; передача не начиналась");return;}
        try{touched.add(plan.operation().id());player.getInventory().setStorageContents(copy(plan.after()));evidence.saveAndVerify(player,plan.proof()).whenComplete((verified,error)->{try(var guard=SuiteState.guard()){if(closing){active.remove(plan.operation().id());return;}if(error!=null||!Boolean.TRUE.equals(verified)){review(plan.operation().id(),"Сохранение инвентаря не подтверждено; повторять выдачу нельзя",error);return;}var state=repository.state();repository.commit(state,state.complete(plan.operation().id())).whenComplete((saved,failed)->{if(failed!=null){failed(plan.operation().id(),failed);return;}try(var committed=SuiteState.guard()){active.remove(plan.operation().id());touched.remove(plan.operation().id());changed.run();tell(player,plan.operation().kind()==Kind.CLAIM?"§aФрагмент получен. Соберите все разные части для реставрации.":"§aАртефакт восстановлен; исходные фрагменты использованы один раз.");}});}});}
        catch(Throwable error){review(plan.operation().id(),"Не удалось подтвердить изменение инвентаря; нужна сверка",error);}
    }
    private void cancelUntouched(Plan plan,String reason){if(touched.contains(plan.operation().id()))return;if(closing){active.remove(plan.operation().id());return;}try{var state=repository.state();repository.commit(state,state.cancelUntouched(plan.operation().id(),reason)).whenComplete((saved,error)->{if(error!=null)failed(plan.operation().id(),error);else try(var guard=SuiteState.guard()){active.remove(plan.operation().id());changed.run();}});}catch(Throwable error){failed(plan.operation().id(),error);}}
    private void review(UUID id,String reason,Throwable error){if(error!=null)plugin.getLogger().log(java.util.logging.Level.WARNING,"Реставрация требует сверки: "+id,error);try{var state=repository.state();repository.commit(state,state.review(id,reason)).whenComplete((saved,failure)->{if(failure!=null)failed(id,failure);else try(var guard=SuiteState.guard()){active.remove(id);changed.run();}});}catch(Throwable failure){failed(id,failure);}}
    private void failed(UUID id,Throwable error){try(var guard=SuiteState.guard()){active.remove(id);plugin.getLogger().log(java.util.logging.Level.WARNING,"Передача реставрации не подтверждена: "+id+". Повторная выдача не выполняется.",error);}}
    private void onPlayer(Player player,UUID id,Runnable action){try(var guard=SuiteState.guard()){if(closing||!plugin.isEnabled())return;SuiteScheduler.entityLater(plugin,player,action,()->{try(var retired=SuiteState.guard()){var plan=active.get(id);if(plan!=null)cancelUntouched(plan,"Игрок вышел до начала передачи");}},1);}}
    private void tell(Player player,String message){if(!closing&&plugin.isEnabled())SuiteScheduler.player(plugin,player,p->p.sendMessage(message));}
    /** Only receipt verification is automatic; a missing receipt leaves the reserved state for administrator review. */
    public CompletionStage<Boolean> reconcile(Player player,UUID id){try(var guard=SuiteState.guard()){
        if(!enabled()||repository.busy()||busy())throw new IllegalStateException("Дождитесь сохранения реставрации.");var op=repository.state().operations().get(id);if(op==null||!op.player().equals(player.getUniqueId()))throw new IllegalArgumentException("Указан другой получатель операции");if(op.phase()==Phase.COMPLETE)return CompletableFuture.completedFuture(true);if(op.phase()!=Phase.ARMED&&op.phase()!=Phase.REVIEW)throw new IllegalArgumentException("Нет неопределённой передачи для сверки");final PlayerSaveEvidence.Prepared proof;try{proof=evidence.prepare(player,id);}catch(java.io.IOException error){return CompletableFuture.failedFuture(error);}var result=new CompletableFuture<Boolean>();active.put(id,new Plan(op,null,null,proof));evidence.verify(proof).whenComplete((verified,error)->{try(var ledger=SuiteState.guard()){if(closing){active.remove(id);result.complete(false);return;}if(error!=null||!Boolean.TRUE.equals(verified)){active.remove(id);if(error!=null)result.completeExceptionally(error);else result.complete(false);return;}var state=repository.state();repository.commit(state,state.complete(id)).whenComplete((saved,failure)->{try(var committed=SuiteState.guard()){active.remove(id);if(failure!=null)result.completeExceptionally(failure);else{changed.run();result.complete(true);}}});}});return result;
    }}
    public void recoverPrepared(){if(closing||busy()||repository.busy()||!repository.writable())return;for(var op:repository.state().operations().values())if(op.phase()==Phase.PREPARED){var state=repository.state();repository.commit(state,state.cancelPrepared(op.id(),"До остановки передача инвентаря не начиналась; резерв освобождён")).whenComplete((saved,error)->{if(error!=null)failed(op.id(),error);});return;}}
    public CompletionStage<Void> prepareClose(){closing=true;return evidence.prepareClose();}public void awaitClosed(){evidence.awaitClosed();}
    private static ItemStack[] copy(ItemStack[] input){return Arrays.stream(input).map(item->item==null?null:item.clone()).toArray(ItemStack[]::new);}private static String encode(ItemStack item){return Base64.getEncoder().encodeToString(item.serializeAsBytes());}
}
